// Command gen writes the palette's Go source, and a log of it that the
// repository ignores.
package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

var palette = []string{"red", "green", "blue"}

func main() {
	out := flag.String("o", "names_gen.go", "generated Go file")
	log := flag.String("log", "", "ignored build output")
	flag.Parse()

	var source strings.Builder
	source.WriteString("// Code generated by internal/gen. DO NOT EDIT.\n\npackage colors\n\n// Names lists the palette.\nvar Names = []string{\n")
	for _, name := range palette {
		fmt.Fprintf(&source, "\t%q,\n", name)
	}
	source.WriteString("}\n")
	if err := os.WriteFile(*out, []byte(source.String()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	if *log != "" {
		if err := os.MkdirAll(filepath.Dir(*log), 0o755); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		if err := os.WriteFile(*log, []byte(strings.Join(palette, "\n")+"\n"), 0o644); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
}
